/**
 * Every expression operator in the MapLibre style spec. Generated by
 * `scripts/generate.mjs`; kept in sync by `test/coverage.test.ts`.
 */
const NAMES = [
  "let",
  "var",
  "literal",
  "semiliteral",
  "array",
  "at",
  "in",
  "index-of",
  "slice",
  "case",
  "match",
  "coalesce",
  "step",
  "interpolate",
  "interpolate-hcl",
  "interpolate-lab",
  "ln2",
  "pi",
  "e",
  "typeof",
  "string",
  "number",
  "boolean",
  "object",
  "collator",
  "format",
  "image",
  "global-state",
  "number-format",
  "to-string",
  "to-number",
  "to-boolean",
  "to-rgba",
  "to-color",
  "rgb",
  "rgba",
  "get",
  "has",
  "length",
  "properties",
  "feature-state",
  "geometry-type",
  "id",
  "zoom",
  "heatmap-density",
  "elevation",
  "line-progress",
  "accumulated",
  "+",
  "*",
  "-",
  "/",
  "%",
  "^",
  "sqrt",
  "log10",
  "ln",
  "log2",
  "sin",
  "cos",
  "tan",
  "asin",
  "acos",
  "atan",
  "min",
  "max",
  "round",
  "abs",
  "ceil",
  "floor",
  "distance",
  "==",
  "!=",
  ">",
  "<",
  ">=",
  "<=",
  "all",
  "any",
  "!",
  "within",
  "is-supported-script",
  "upcase",
  "downcase",
  "concat",
  "resolved-locale",
  "split",
  "join",
] as const

/** The name of a MapLibre expression operator, e.g. `"get"` or `"+"`. */
export type OperatorName = (typeof NAMES)[number]

/** @internal */
export const OPERATOR_NAMES: ReadonlySet<string> = /* @__PURE__ */ new Set(NAMES)

/** `true` if `value` is an expression array (its head is a spec operator). @internal */
export function isExpression(value: unknown): value is readonly [OperatorName, ...unknown[]] {
  return Array.isArray(value) && typeof value[0] === "string" && OPERATOR_NAMES.has(value[0])
}
